<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/DocsAccessService.php';Auth::requireLogin();try{$doc=DocsAccessService::requireDoc((int)($_GET['id']??0));}catch(Throwable $e){http_response_code(404);exit('مستند در دسترس نیست.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/employee/doc-view.php?id='.$doc['id']);}try{DocsAccessService::logRead((int)$doc['id'],true);Auth::log((int)Auth::user()['id'],'docs_read_confirmed','docs_articles',(int)$doc['id']);flash('تایید مطالعه ثبت شد.');}catch(Throwable $e){error_log('Doc confirm: '.$e->getMessage());flash('ثبت تایید مطالعه انجام نشد.','danger');}redirect('/employee/doc-view.php?id='.$doc['id']);}try{DocsAccessService::logRead((int)$doc['id']);}catch(Throwable $e){error_log('Doc read: '.$e->getMessage());}$log=Database::fetch('SELECT * FROM docs_read_logs WHERE doc_id=? AND user_id=?',[(int)$doc['id'],(int)Auth::user()['id']]);$pageTitle=$doc['title'];$adminExtraStylesheets=['/assets/css/workforce.css'];require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1><?=e($doc['title'])?></h1><div class="doc-meta"><span><?=e($doc['category_title']?:'بدون دسته')?></span><span><?=e(format_jalali_date($doc['updated_at']))?></span></div></div><a class="btn" href="/employee/docs.php">بازگشت</a></div><article class="card doc-content"><?=DocsAccessService::sanitize($doc['content'])?></article><?php if($doc['attachment_path']):?><section class="card"><h2>فایل پیوست</h2><a class="btn btn-primary" href="/admin/doc-download.php?id=<?=$doc['id']?>"><?=e($doc['attachment_name']?:'دانلود پیوست')?></a></section><?php endif?><?php if($doc['require_read_confirmation']):?><section class="card"><?php if($log&&$log['confirmed_at']):?><p class="workforce-status status-valid">مطالعه این مستند در <?=e(format_jalali_date($log['confirmed_at']))?> تایید شده است.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><button class="btn btn-primary">این مستند را مطالعه کردم</button></form><?php endif?></section><?php endif?><?php require __DIR__.'/../views/partials/admin-footer.php';?>
